const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
async function get(u){const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw Error();return r.json()}
function timeSeconds(value){const text=String(value??'').trim();if(!text||/^(dnf|dns|n\/a|not raced yet)$/i.test(text))return null;const parts=text.split(':').map(Number);if(!parts.length||parts.some(n=>!Number.isFinite(n)))return null;return parts.length===3?parts[0]*3600+parts[1]*60+parts[2]:parts.length===2?parts[0]*60+parts[1]:parts[0]}
async function render(){const id=new URLSearchParams(location.search).get('id');if(!id){$('#rider-content').innerHTML='<p class="empty">Choose a rider from the live results to view their complete record.</p>';return}try{const rider=await get('/api/public/riders/'+encodeURIComponent(id)),records=rider.records||[],first=records[0]||{},bib=rider.bib||first.bib||'',fastest=records.filter(x=>timeSeconds(x.time)!=null).reduce((best,x)=>!best||timeSeconds(x.time)<timeSeconds(best.time)?x:best,null),category=String(rider.category||''),categoryClass=category.toLowerCase().replace(/[^a-z]+/g,'');const chipReturn=rider.chipReturned?`<section class="chip-card chip-card--returned"><div><span>Timing chip</span><h2>Returned</h2><p>${rider.chipReturnInfo?esc(rider.chipReturnInfo):'This timing chip has been returned.'}</p></div></section>`:'';document.title=`${rider.name} · OWAR 2026`;$('#back-results').href=first.tournament?'/?event='+encodeURIComponent(first.tournament.toLowerCase()):'/';$('#rider-content').innerHTML=`<section class="rider-hero"><div class="rider-number">${esc(bib||'—')}</div><div><div class="eyebrow">${esc(first.tournament||'Rider')}</div><h1>${esc(rider.name)}</h1><p>Bib ${esc(bib||'—')} · ${esc(first.tournament||'OWAR 2026')}${category?` <span class="rider-category rider-category--${categoryClass}">${esc(category)}</span>`:''}</p></div></section><section class="rider-stats"><div><span>Recorded races</span><strong>${records.length}</strong></div><div><span>Fastest time</span><strong>${esc(fastest?.time||'—')}</strong></div></section><section class="race-table history-card"><div class="history-heading"><span>Current event</span><h2>Every recorded time</h2></div><div class="table-scroll"><table class="rider-times"><colgroup><col class="rider-time-stage"><col class="rider-time-race"><col class="rider-time-position"><col class="rider-time-value"></colgroup><thead><tr><th>Stage</th><th>Race</th><th>Position</th><th>Time</th></tr></thead><tbody>${records.flatMap(x=>{const laps=x.laps?.length?x.laps:[{lap_number:null,time:x.time}],fastest=Math.min(...laps.map(lap=>timeSeconds(lap.time)).filter(value=>value!=null));return laps.map((lap,index)=>{const isFastest=timeSeconds(lap.time)===fastest;return `<tr class="${isFastest?'rider-lap--fastest':''}"><td>${index===0?`<span class="history-stage">${esc(x.stage||x.level||'Results')}</span>`:''}</td><td>${esc(x.race)}</td><td>${index===0?esc(x.position):''}</td><td class="time">${isFastest?`<strong>${esc(lap.time)}</strong>`:esc(lap.time)}</td></tr>`})}).join('')||'<tr><td colspan="4">No recorded times yet.</td></tr>'}</tbody></table></div></section>${chipReturn}`}catch{$('#rider-content').innerHTML='<p class="empty">This rider record is not available yet.</p>'}}
render();
